page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

apiNamespace apiV1 {
  middlewareConfigFn: import { apiNamespaceMiddlewareFn } from "@src/apis",
  path: "/api"
}

api getStatus {
  fn: import { getStatus } from "@src/apis",
  httpRoute: (GET, "/api/status"),
  auth: false
}

api postEcho {
  fn: import { postEcho } from "@src/apis",
  httpRoute: (POST, "/api/echo"),
  auth: false,
  middlewareConfigFn: import { echoMiddlewareFn } from "@src/apis"
}

import cors from 'cors';
import type { MiddlewareConfigFn } from 'wasp/server';
import { config } from 'wasp/server';

/**
 * Global server middleware.
 *
 * - Extends the allowed CORS origins to include http://localhost:5000 while
 *   preserving the existing default origins (e.g. http://localhost:3000).
 * - Adds a custom middleware that sets the `X-Global: enabled` response header.
 */
export const serverMiddlewareFn: MiddlewareConfigFn = (middlewareConfig) => {
  // Replace the default `cors` middleware with one that also accepts the
  // http://localhost:5000 origin.
  middlewareConfig.set(
    'cors',
    cors({
      origin: [...config.allowedCORSOrigins, 'http://localhost:5000'],
    })
  );

  // Custom middleware that sets a response header on every request.
  middlewareConfig.set('x-global-header', (_req, res, next) => {
    res.setHeader('X-Global', 'enabled');
    next();
  });

  return middlewareConfig;
};

import express from 'express';
import type { MiddlewareConfigFn } from 'wasp/server';

/**
 * Per-path (namespace) middleware applied to every api under `/api`.
 * Sets the `X-Api-Namespace: v1` response header.
 */
export const apiNamespaceMiddlewareFn: MiddlewareConfigFn = (middlewareConfig) => {
  middlewareConfig.set('x-api-namespace-header', (_req, res, next) => {
    res.setHeader('X-Api-Namespace', 'v1');
    next();
  });
  return middlewareConfig;
};

/**
 * Per-api middleware applied only to `POST /api/echo`.
 *
 * - Replaces the default JSON body parser with a raw body parser, so the
 *   handler receives the unparsed request body as a Buffer on `req.body`.
 * - Adds a custom middleware that sets the `X-Echo: raw` response header.
 */
export const echoMiddlewareFn: MiddlewareConfigFn = (middlewareConfig) => {
  middlewareConfig.delete('express.json');
  middlewareConfig.set('express.raw', express.raw({ type: '*/*' }));

  middlewareConfig.set('x-echo-header', (_req, res, next) => {
    res.setHeader('X-Echo', 'raw');
    next();
  });

  return middlewareConfig;
};

/**
 * GET /api/status -> { "status": "ok" }
 */
export const getStatus = (_req: any, res: any) => {
  res.json({ status: 'ok' });
};

/**
 * POST /api/echo -> { "bytes": <byte length of raw request body> }
 *
 * Because the per-api middleware swapped the JSON parser for a raw parser,
 * `req.body` is a Buffer containing the unparsed request body.
 */
export const postEcho = (req: any, res: any) => {
  const rawBody: Buffer | undefined = req.body;
  const bytes = rawBody ? rawBody.length : 0;
  res.json({ bytes });
};

